# Generated by build.py from recipe.yml for recipe ws-list-a-folder-over-websocket. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/notes', 'plain', 'plain/notes' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/notes/today.txt'), "nothing happened`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/notes/today.txt'), "nothing happened`n")
cmd /c 'mkdir -p logs'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'logs/surl.log', '--directory', 'site', '--list-directories', 'ws://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe ws://127.0.0.1:8080/ } finally { Stop-Process $server0 }
